begin read only;set local statement_timeout='3s';with r as materialized (select fabric_id,after_hash,before_row,rolled_back from advisory.index_job_items where job_id='ac425f78-f6ec-4623-97bb-df8763d79d5a'::uuid) select jsonb_build_object('observedAt',clock_timestamp(),'job',(select to_jsonb(j) from advisory.index_jobs j where id='ac425f78-f6ec-4623-97bb-df8763d79d5a'::uuid),'receipts',(select count(*) from r),'matchedHashes',(select count(*) from r join advisory.knowledge_search k using(fabric_id) where k.source_hash=r.after_hash and not r.rolled_back),'newEligibleRows',(select count(*) from r where before_row is null),'historicalNoops',(select count(*) from r where before_row is not null),'receiptIdentityHash', (select encode(sha256(convert_to(coalesce(string_agg(fabric_id,E'\n' order by fabric_id collate "C"),''),'UTF8')),'hex') from r),'receiptContentHash',(select encode(sha256(convert_to(coalesce(string_agg(fabric_id||':'||after_hash,E'\n' order by fabric_id collate "C"),''),'UTF8')),'hex') from r),'totalKnowledge',(select count(*) from advisory.knowledge_search),'databaseBytes',pg_database_size(current_database()),'advisoryBytes',(select sum(pg_total_relation_size(c.oid)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='advisory' and c.relkind='r'),'migrationCount',(select count(*) from supabase_migrations.schema_migrations),'latestMigration',(select max(version) from supabase_migrations.schema_migrations),'permissionRestored',(not pg_has_role('postgres','advisory_indexer','SET') and (select count(*) from pg_auth_members where roleid='advisory_indexer'::regrole)=1 and exists(select 1 from pg_auth_members where roleid='advisory_indexer'::regrole and member='postgres'::regrole and grantor='supabase_admin'::regrole and admin_option and not inherit_option and not set_option))) as value;commit;
